import{_ as o,b as i,c as d,d as a,t as c,C as v,u as n}from"./index-I5uTs6b4.js";const u={class:"level-page"},b={class:"level-content"},f={class:"level-title"},p={__name:"Level23",props:{id:{type:String,required:!0}},setup(s){const l=n();function e(){sessionStorage.setItem("skipIntro","1"),l.push("/")}return(r,t)=>(i(),d("div",u,[a("button",{class:"back-btn",onClick:e},"← Back to Index"),a("div",b,[a("h1",f,"SI-"+c(s.id),1),t[0]||(t[0]=v('<p class="level-name" data-v-b3556af7>&quot;县&quot;</p><div class="section" data-v-b3556af7><h2 data-v-b3556af7>生存难度：孤立效应</h2><div class="difficulty" data-v-b3556af7><ul class="class-list" data-v-b3556af7><li data-v-b3556af7><span class="class-bullet stable" data-v-b3556af7></span> 稳定</li><li data-v-b3556af7><span class="class-bullet mental" data-v-b3556af7></span> 精神影响</li><li data-v-b3556af7><span class="class-bullet entity" data-v-b3556af7></span> 大量无害实体</li></ul></div></div><div class="section" data-v-b3556af7><h2 data-v-b3556af7>描述</h2><p data-v-b3556af7>Level SI-23 &quot;县&quot; 是一个十分独特的层级。本层级内的空间形态不同于任何已知的空间形态，其特征是与层级内流浪者的感知有高度一致性。这意味着，该层级没有固定的形态。M.E.G. 根据若干深入层级并成功定居的流浪者传来的报告分析出该层级具有&quot;孤立效应&quot;。</p><p data-v-b3556af7>由于本层级的&quot;孤立效应&quot;特征，M.E.G. 无法准确描述其内部形态，但根据流浪者的报告可以发现该层级内部形态存在某种共性：</p><ol class="common-list" data-v-b3556af7><li data-v-b3556af7>在初次切入层级 SI-23 时，当地时间均为深夜或凌晨，夜空晴朗无星。</li><li data-v-b3556af7>层级 SI-23 的内部场景均与前厅中存在的中国西南地区的县级市高度吻合。</li><li data-v-b3556af7>层级 SI-23 内的所有室外灯光均为橙黄色，灯下必定存在一种体表类似木屑，散发出木头气味的飞蛾。这种飞蛾种群数量极大，且拥有智慧，能与流浪者进行精神交流。M.E.G. 暂且称呼其为&quot;木蛾&quot;。</li><li data-v-b3556af7>层级 SI-23 内的气味具有强烈的心理暗示作用（部分激进的研究人员认为其具有成瘾性）。所有流浪者都不约而同地在报告中花大篇幅描写层级内的气味，且明显带有正面的主观色彩。</li></ol><p data-v-b3556af7>奇怪的是，&quot;木蛾&quot;无法以任何已知的方式带出层级 SI-23——有一些流浪者切出层级 SI-23，他们试图带出一些&quot;木蛾&quot;样本，可所有&quot;木蛾&quot;最终都变成了极为普通的铅笔屑。而切出的流浪者也会快速忘记层级内部的所有景象——但对于层级内的气味，他们记得一清二楚。</p><p data-v-b3556af7>值得一提的是，迄今为止，进入该层级或曾进入过的所有流浪者都维持着生理健康，这在理性客观而冷漠残酷的后室世界中十分罕见。但也有部分流浪者在该层级长期独居后表现出了不同程度的精神损伤，均不致命。目前 M.E.G. 认为其致病原因是过度孤独。</p></div>',3))])]))}},_=o(p,[["__scopeId","data-v-b3556af7"]]);export{_ as default};
